(require '[seon.db :as db] '[seon.cluster.boot :as boot] '[seon.cluster.store :as store] '[seon.cluster.registry :as registry] '[seon.fn :as index] '[seon.fn.analyzer :as analyzer] '[seon.program :as program] '[seon.schema :as schema] '[seon.test-support :as support] '[seon.id :as id] '[clojure.java.io :as io] '[clojure.string :as str] '[clj-kondo.impl.cache :as kondo.cache] '[clj-kondo.impl.core :as kondo.core] '[clj-kondo.core :as clj-kondo] '[clj-kondo.core :as kondo] '[cognitect.transit :as transit])
(do (def source-container (eval (let [[_ name doc metadata & body] (read-string "(defn- source-container\n  \"The file whose bytes own an analysis: the source file, or its containing jar.\"\n  {:malli/schema [:=> [:cat :string] :string]}\n  [filename]\n  (if-let [jar-end (str/index-of filename \".jar:\")]\n    (subs filename 0 (+ jar-end 4))\n    filename))\n")] (list 'let (read-string "[]") (list* 'fn name body))))) (def classpath-after (eval (let [[_ name doc metadata & body] (read-string "(defn- classpath-source\n  \"The directory file this JVM's classpath loads for `namespace-name`: a\n  first-party file (the `:test` alias's `.` puts `dev_cache.clj` there) or a\n  directory dependency's (`:local/root`, a git dep), or the jar containing\n  the namespace. The system loader answers, not a thread's context loader\n  (`seon.sci.eval`). Content checks cover jars as well as directory files;\n  clj-kondo's path-only skip mark is not proof of their bytes. Returns an\n  empty vector when the namespace has no source on this classpath.\"\n  {:malli/schema [:=> [:cat :symbol] [:vector :string]]}\n  [namespace-name]\n  (let [base (-> (str namespace-name) (str/replace \"-\" \"_\") (str/replace \".\" \"/\"))]\n    (into [] (take 1)\n          (keep (fn [extension]\n            (when-let [url (.getResource (ClassLoader/getSystemClassLoader) (str base extension))]\n              (case (.getProtocol url)\n                \"file\" (.getCanonicalPath (io/file (.toURI url)))\n                \"jar\" (.getCanonicalPath\n                       (io/file (.toURI (.getJarFileURL ^java.net.JarURLConnection (.openConnection url)))))\n                nil)))\n          [\".clj\" \".cljc\"]))))\n")] (list 'let (read-string "[]") (list* 'fn name body))))) (def record-after (eval (let [[_ name doc metadata & body] (read-string "(defn- record-entry-digests!\n  \"Record each namespace's content proof beside kondo's entry. Hash each\n  distinct source or jar once, including when it defines many namespaces.\"\n  {:malli/schema [:=> [:cat :string :map] :nil]}\n  [root result]\n  (let [entries (into #{}\n                      (keep (fn [{namespace-name :name filename :filename}]\n                              (when (and (symbol? namespace-name) (string? filename))\n                                [(kondo.cache/cache-file root\n                                   (if (str/ends-with? filename \".cljc\") :cljc :clj) namespace-name)\n                                 (source-container filename)])))\n                      (:namespace-definitions (:analysis result)))\n        digests (into {} (comp (map second) (distinct)\n                              (filter #(.isFile (io/file %)))\n                              (map #(vector % (file-digest %)))) entries)]\n    (kondo.cache/with-thread-lock\n      (kondo.cache/with-cache root 6\n        (doseq [[^java.io.File cache-file source] entries\n                :when (and (.isFile cache-file) (contains? digests source))]\n          (spit (entry-digest-file (.getPath cache-file)) (get digests source))))))\n  nil)\n")] (list 'let (read-string "[source-container source-container entry-digest-file @#'analyzer/entry-digest-file file-digest @#'analyzer/file-digest]") (list* 'fn name body))))) (def stale-after (eval (let [[_ name doc metadata & body] (read-string "(defn- stale-cache-entries\n  \"The cache entries this analysis could have read that do not answer for the\n  current bytes of their source.\n\n  clj-kondo loads a cached namespace by NAME with no content check\n  (`reference-code/clj-kondo/src/clj_kondo/impl/cache.clj:127-144`,\n  `load-when-missing`), and only for namespaces the linted files use, so\n  only those entries are examined — the work is proportional to the analysis,\n  not to the cache. An entry is stale when it was built from other bytes than\n  its source now holds, or has no recorded content proof for its current\n  source. Timestamps never override a differing digest. Also stale when its source is gone\n  or is the stdin buffer. In the shared cache, a namespace absent from both\n  this analysis and the current classpath is foreign; an old cache entry is\n  not authority to restore a dependency the classpath no longer loads.\n  Kondo names jar sources `<jar>:<entry>` under canonical paths\n  (clj_kondo/impl/core.clj:289-291); hash the containing jar once, not once per\n  namespace. Each stale entry names its current source when it has one, and a\n  namespace this run does not define (first-party or a directory dependency's)\n  names the file this classpath loads (`classpath-source`), so the caller can rebuild it.\n\n  `shared?` is true for the checkout's own cache under `.clj-kondo/`. An\n  explicitly supplied cache root belongs to its caller, whose every source\n  may rebuild it and none of whose sources is foreign.\"\n  {:malli/schema\n   [:=> [:cat :string :boolean [:map [:analysis {:optional true} :map]]]\n    [:map\n     [::analyzer/examined :int]\n     [::analyzer/stale [:vector [:map [::analyzer/cache-file :string] [::analyzer/namespace :symbol]\n                        [::analyzer/language [:enum :clj :cljc :cljs]]\n                        [::analyzer/reason [:enum ::analyzer/stdin ::analyzer/source-absent ::analyzer/foreign ::analyzer/modified]]\n                        [::analyzer/source {:optional true} :string]]]]]]}\n  [root shared? result]\n  (let [analysis (:analysis result)\n        defined (into {}\n                      (keep (fn [{namespace-name :name filename :filename}]\n                              (when (string? filename)\n                                [namespace-name\n                                 (.getCanonicalPath (io/file filename))])))\n                      (:namespace-definitions analysis))\n        used (into (set (keep :to (:namespace-usages analysis)))\n                   (keep :to (:var-usages analysis)))\n        examined\n        (for [namespace-name (sort-by str used)\n              :when (symbol? namespace-name)\n              language [:clj :cljc :cljs]\n              :let [file (kondo.cache/cache-file root language namespace-name)]\n              :when (and (.isFile file)\n                         (not (java.nio.file.Files/isSymbolicLink (.toPath file))))]\n          [namespace-name language file\n           (:filename (with-open [input (io/input-stream file)]\n                        (transit/read (transit/reader input :json))))])\n        cached-sources (into {} (keep (fn [[namespace-name _ _ filename]]\n                                        (when (string? filename)\n                                          [namespace-name (analyzed-source-path (source-container filename))]))) examined)\n        current-files (into {} (map (fn [namespace-name]\n                                     [namespace-name\n                                      (or (some-> (get defined namespace-name) source-container)\n                                          (first (classpath-source namespace-name))\n                                          (when-not shared? (get cached-sources namespace-name)))]))\n                            (distinct (map first examined)))\n        digests (into {} (comp (filter some?) (distinct)\n                              (filter #(.isFile (io/file %)))\n                              (map #(vector % (file-digest %))))\n                      (vals current-files))]\n    {::analyzer/examined (count examined)\n     ::analyzer/stale\n     (into []\n        (for [[namespace-name language ^java.io.File file filename] examined\n              :when (string? filename)\n              :let [current-file (get current-files namespace-name)\n                    recorded (io/file (entry-digest-file (.getPath file)))\n                    current-source? (contains? digests current-file)\n                    same-bytes? (and current-source? (.isFile recorded)\n                                     (= (slurp recorded) (get digests current-file)))\n                    reason (cond\n                             same-bytes? nil\n                             (= \"<stdin>\" filename) ::analyzer/stdin\n                             current-source? ::analyzer/modified\n                             (and shared? (nil? current-file)) ::analyzer/foreign\n                             :else ::analyzer/source-absent)]\n              :when reason]\n          (cond-> {::analyzer/cache-file (.getPath file)\n                   ::analyzer/namespace namespace-name\n                   ::analyzer/language language\n                   ::analyzer/reason reason}\n            current-source? (assoc ::analyzer/source current-file))))}))\n\n(declare unanalyzed-namespaces)\n")] (list 'let (read-string "[analyzed-source-path @#'analyzer/analyzed-source-path source-container source-container classpath-source classpath-after entry-digest-file @#'analyzer/entry-digest-file file-digest @#'analyzer/file-digest]") (list* 'fn name body))))) (def invoke-after (eval (let [[_ name doc metadata & body] (read-string "(defn- invoke-kondo\n  \"Run clj-kondo once, then rebuild any cache entry the run read that does not\n  answer for current bytes and run once more.\n\n  The rerun is the whole cost of a stale entry; with none, the check reads\n  only the entries of the namespaces the analysis used. `::analyzer/cache` reports\n  what was examined, rebuilt and deleted. An entry still stale after the\n  rebuild throws the declared analysis source-change refusal.\"\n  {:malli/schema [:=> [:cat [:map [:lint [:vector :string]]]]\n                  [:map [::analyzer/cache [:map [::analyzer/examined :int] [::analyzer/stale [:vector :map]]\n                                  [::analyzer/rebuilt [:vector :string]]]]]]}\n  [options]\n  (let [options (merge {:lang :clj\n                        :config-dir config-directory\n                        :cache-dir cache-directory\n                        :cache true\n                        :repro true\n                        :config analysis-config}\n                       options)\n        cached? (not (false? (:cache options)))\n        root (when cached?\n               (.getCanonicalPath ^java.io.File\n                (kondo.core/resolve-cache-dir (:config-dir options) true (:cache-dir options))))\n        ;; The checkout's own cache, however the caller spelled it: publication\n        ;; hands `<root>/.clj-kondo/.cache` explicitly (`seon.fn/analyzed-files`).\n        shared? (and root\n                     (= root (.getCanonicalPath ^java.io.File\n                              (kondo.core/resolve-cache-dir config-directory true cache-directory))))\n        ;; Every run that may write entries records their content digests.\n        kondo-run! (fn [run-options]\n               (let [result (clj-kondo/run! run-options)]\n                 (when root (record-entry-digests! root result))\n                 result))\n        check (fn [result]\n                (if root\n                  (kondo.cache/with-thread-lock\n                    (kondo.cache/with-cache root 6\n                      (stale-cache-entries root shared? result)))\n                  {::analyzer/examined 0 ::analyzer/stale []}))\n        first-run (kondo-run! options)\n        ;; A namespace kondo holds no entry for (first-party outside the\n        ;; publication roots, or a directory dependency's) is analyzed from\n        ;; the file the classpath loads.\n        classpath-files (when root\n                      (into [] (comp (mapcat classpath-source) (distinct))\n                            (unanalyzed-namespaces root (:analysis first-run))))\n        result (if (seq classpath-files)\n                 (do (kondo-run! (assoc options :lint classpath-files))\n                     (kondo-run! options))\n                 first-run)\n        {::analyzer/keys [examined stale]} (check result)]\n    (if (empty? stale)\n      (cond-> (assoc result ::analyzer/cache {::analyzer/examined examined ::analyzer/stale [] ::analyzer/rebuilt []})\n        root (assoc ::analyzer/cache-root root))\n      (let [sources (into [] (comp (keep ::analyzer/source) (distinct)) stale)]\n        (kondo.cache/with-thread-lock\n          (kondo.cache/with-cache root 6\n            (doseq [{::analyzer/keys [cache-file]} stale]\n              (java.nio.file.Files/deleteIfExists (.toPath (io/file cache-file))))))\n        ;; Rebuild each checkout-owned entry from its current bytes; this\n        ;; run's own findings belong to its files' analyses, not to this one.\n        (when (seq sources)\n          (kondo-run! (assoc options :lint sources)))\n        (let [rerun (kondo-run! options)\n              remaining (::analyzer/stale (check rerun))]\n          ;; An entry still stale after its rebuild was changed by a concurrent\n          ;; source edit: the declared analysis source-change refusal\n          ;; (`:seon.fn/index-refused-error`), naming the changed paths. The\n          ;; operator request returns it as refused (`seon.cluster.boot/request!`).\n          (when (seq remaining)\n            (throw (ex-info \"Source changed during analysis; clj-kondo cache entries changed again.\"\n                            {:seon.fn/index-refused true\n                             :seon.cluster.boot/disposition :refused\n                             :seon.cluster.source/phase :analysis\n                             :seon.error/message \"Source changed during analysis; clj-kondo cache entries changed again.\"\n                             :seon.source/changed-paths\n                             (into [] (comp (map #(or (::analyzer/source %) (::analyzer/cache-file %))) (distinct))\n                                   remaining)\n                             ::analyzer/stale remaining\n                             ::analyzer/lint (:lint options)})))\n          (assoc rerun ::analyzer/cache {::analyzer/examined examined ::analyzer/stale stale ::analyzer/rebuilt sources}\n                 ::analyzer/cache-root root))))))\n")] (list 'let (read-string "[stale-cache-entries stale-after config-directory @#'analyzer/config-directory cache-directory @#'analyzer/cache-directory analysis-config @#'analyzer/analysis-config record-entry-digests! record-after classpath-source classpath-after unanalyzed-namespaces @#'analyzer/unanalyzed-namespaces]") (list* 'fn name body))))))
